// Complete inheritance hierarchy and polymorphic operations are implemented in this standalone model.
class GymMember {protected String id;protected int fee,sessions;private int[] history=new int[10];private int count;public GymMember(String i,int f){if(i==null||i.trim().length()<4||f<=0)throw new IllegalArgumentException();id=i;fee=f;}public void attendSession(){sessions++;}public int getSessionsAttended(){return sessions;}public String displayInfo(){return "Standard Member | Sessions: "+sessions;}protected void chargeLateFee(int n){if(count==10)throw new IllegalStateException();history[count++]=n;}public int[] getLateFeeHistory(){return java.util.Arrays.copyOf(history,count);}public int getTotalLateFees(){return java.util.Arrays.stream(history,0,count).sum();}}
class PremiumMember extends GymMember {String trainer;public PremiumMember(String i,int f,String t){super(i,f);trainer=t;}@Override public String displayInfo(){return "Premium Member | Trainer: "+trainer+" | Sessions: "+sessions;}@Override protected void chargeLateFee(int n){super.chargeLateFee(n/2);}public String getTrainerName(){return trainer;}}
class EliteMember extends PremiumMember {String locker;public EliteMember(String i,int f,String t,String l){super(i,f,t);locker=l;}@Override public String displayInfo(){return "Elite Member | Trainer: "+trainer+" | Locker: "+locker+" | Sessions: "+sessions;}}
class GroupClassMember extends GymMember {String className;public GroupClassMember(String i,int f,String c){super(i,f);className=c;}@Override public String displayInfo(){return "Group Class Member | Class: "+className+" | Sessions: "+sessions;}}
public class Problem2_GymMembershipHierarchy {static String classifyGeneration(GymMember m){if(m instanceof EliteMember)return "Multilevel descendant (3 generations deep)";if(m instanceof GroupClassMember)return "Hierarchical sibling (independent branch)";if(m instanceof PremiumMember)return "Premium branch";return "Base member";}static int getTotalSessionsAttended(GymMember[] m){int n=0;for(GymMember x:m)n+=x.getSessionsAttended();return n;}static String batchPrint(GymMember[] m){StringBuilder b=new StringBuilder();for(GymMember x:m){if(b.length()>0)b.append(" | ");b.append(x.displayInfo());if(x instanceof PremiumMember)b.append(" [Trainer via downcast: ").append(((PremiumMember)x).getTrainerName()).append("]");}return b.toString();}public static void main(String[]x){GymMember[] m={new GymMember("MEM1",1000),new PremiumMember("MEM2",2000,"Coach Riya"),new EliteMember("MEM3",3000,"Coach Arjun","L12"),new GroupClassMember("MEM4",1500,"Zumba")};for(GymMember v:m)System.out.println(v.displayInfo());System.out.println(classifyGeneration(m[2]));}}